public record Order(String id, List<LineItem> items) {
    public Order {                        // compact constructor: copy on the way in
        id = Objects.requireNonNull(id);
        items = List.copyOf(items);       // snapshot, not a view
    }
    public Order withItem(LineItem extra) {
        var next = new ArrayList<>(items);
        next.add(extra);
        return new Order(id, next);
    }
}

