public final class DateRange {
    private final LocalDate start, end;
    private final List<String> tags;
    public DateRange(LocalDate start, LocalDate end, List<String> tags) {
        this.tags = List.copyOf(tags);          // copy before validating (TOCTOU)
        if (end.isBefore(start)) throw new IllegalArgumentException("end before start");
        this.start = start;
        this.end = end;
    }
    public DateRange withEnd(LocalDate newEnd) { return new DateRange(start, newEnd, tags); }
}
